1	"use client";
2	
3	import React from "react";
4	import { AlertTriangle } from "lucide-react";
5	import { Button } from "@/components/ui/button";
6	import { logClientError } from "@/lib/logClientError";
7	
8	interface Props {
9	  children: React.ReactNode;
10	}
11	
12	interface State {
13	  hasError: boolean;
14	  error: Error | null;
15	}
16	
17	class AdminErrorBoundary extends React.Component<Props, State> {
18	  constructor(props: Props) {
19	    super(props);
20	    this.state = { hasError: false, error: null };
21	  }
22	
23	  static getDerivedStateFromError(error: Error): State {
24	    return { hasError: true, error };
25	  }
26	
27	  componentDidCatch(error: Error, info: React.ErrorInfo) {
28	    const componentLine = info.componentStack?.split("\n").find((l) => l.trim().startsWith("at "));
29	    const source = componentLine?.trim().replace(/^at /, "").split(" ")[0] ?? "Admin";
30	    logClientError(
31	      "ReactRenderError",
32	      source,
33	      error.message,
34	      error.stack,
35	      { componentStack: info.componentStack?.slice(0, 1000), area: "admin" },
36	    );
37	  }
38	
39	  render() {
40	    if (this.state.hasError) {
41	      return (
42	        <div className="flex flex-col items-center justify-center py-16 text-center">
43	          <AlertTriangle className="h-10 w-10 text-destructive mb-3" />
44	          <p className="text-lg font-semibold text-foreground">Something went wrong</p>
45	          <p className="text-sm text-muted-foreground mt-1 max-w-md">{this.state.error?.message}</p>
46	          <Button
47	            variant="outline"
48	            className="mt-4"
49	            onClick={() => this.setState({ hasError: false, error: null })}
50	          >
51	            Try again
52	          </Button>
53	        </div>
54	      );
55	    }
56	    return this.props.children;
57	  }
58	}
59	
60	export default AdminErrorBoundary;
