21	interface StatsData {
22	  total_users: number;
23	  total_jobs: number;
24	  total_resumes: number;
25	  total_credits_used: number;
26	  total_revenue: number;
27	  mrr_30d: number;
28	  conversion_rate: number;
29	  active_users_7d: number;
30	  active_users_30d: number;
31	  avg_resumes_per_job: number;
32	  resumes_today: number;
33	  resumes_week: number;
34	  resumes_month: number;
35	  daily_chart: { date: string; credits: number; jobs: number; signups: number; revenue: number }[];
