51	  const [activePreset, setActivePreset] = useState<number>(30);
52	
53	  const fromISO = dateRange?.from?.toISOString().slice(0, 10);
54	  const toISO = dateRange?.to?.toISOString().slice(0, 10);
55	
56	  const { data: stats, isLoading, isFetching } = useQuery({
57	    queryKey: ["admin_stats", fromISO, toISO],
58	    queryFn: async () => {
59	      const { data, error } = await supabase.functions.invoke("admin-stats", {
60	        body: { from: fromISO, to: toISO },
61	      });
62	      if (error) throw error;
63	      return data as StatsData;
64	    },
65	  });
66	
67	  const { data: emailConfig } = useQuery({
68	    queryKey: ["admin_email_config"],
69	    queryFn: async () => {
70	      const { data, error } = await supabase.from("platform_config").select("email_ingestion_enabled").limit(1).single();
71	      if (error) throw error;
72	      return data;
73	    },
74	    staleTime: 5 * 60 * 1000,
75	  });
76	
77	  const selectPreset = (days: number) => {
78	    setActivePreset(days);
79	    setDateRange({ from: subDays(new Date(), days), to: new Date() });
80	  };
81	
82	  const handleRangeSelect = (range: DateRange | undefined) => {
83	    setDateRange(range);
84	    setActivePreset(0); // clear preset when custom selected
85	  };
86	
87	  const rangeDays = dateRange?.from && dateRange?.to
88	    ? Math.ceil((dateRange.to.getTime() - dateRange.from.getTime()) / (1000 * 60 * 60 * 24))
89	    : 30;
90	  const rangeLabel = activePreset
91	    ? PRESETS.find(p => p.days === activePreset)?.label ?? `${rangeDays}d`
92	    : dateRange?.from && dateRange?.to
93	      ? `${format(dateRange.from, "MMM d")} – ${format(dateRange.to, "MMM d, yyyy")}`
94	      : "30 days";
95	
96	  const cards = [
97	    { label: "Total Users", value: stats?.total_users, icon: Users, color: "text-blue-500" },
98	    { label: "Active Users (7d)", value: stats?.active_users_7d, icon: UserCheck, color: "text-emerald-500" },
99	    { label: "Total Jobs", value: stats?.total_jobs, icon: Briefcase, color: "text-primary" },
100	    { label: "Resumes Processed", value: stats?.total_resumes, icon: FileText, color: "text-amber-500", subtitle: `Today: ${stats?.resumes_today ?? 0} · Week: ${stats?.resumes_week ?? 0}` },
101	    { label: "Credits Consumed", value: stats?.total_credits_used, icon: Coins, color: "text-purple-500" },
102	    { label: "Total Revenue", value: stats?.total_revenue != null ? `$${(stats.total_revenue / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : undefined, icon: DollarSign, color: "text-green-500", subtitle: `Period: $${((stats?.mrr_30d ?? 0) / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` },
103	    { label: "Conversion Rate", value: stats?.conversion_rate != null ? `${stats.conversion_rate}%` : undefined, icon: TrendingUp, color: "text-rose-500" },
104	    { label: "Avg Resumes/Job", value: stats?.avg_resumes_per_job, icon: BarChart3, color: "text-cyan-500" },
105	  ];
106	
107	  const chartInterval = rangeDays > 90 ? Math.floor(rangeDays / 15) : rangeDays > 30 ? 7 : 4;
108	
109	  const chartData = stats?.daily_chart?.map((d) => ({
110	    ...d,
111	    label: new Date(d.date).toLocaleDateString("en-US", { month: "short", day: "numeric" }),
112	    revenue_dollars: d.revenue / 100,
113	  })) ?? [];
114	
115	  const tooltipStyle = { borderRadius: 8, border: "1px solid hsl(var(--rk-border))", background: "hsl(var(--rk-card))" };
116	
117	  return (
118	    <div className="space-y-6">
119	      <div className="flex items-center justify-between flex-wrap gap-3">
120	        <h2 className="text-xl font-semibold">Dashboard Overview</h2>
121	        <div className="flex items-center gap-2 flex-wrap">
122	          {/* Preset buttons */}
123	          {PRESETS.map(({ label, days }) => (
124	            <Button
125	              key={days}
126	              variant={activePreset === days ? "default" : "outline"}
127	              size="sm"
128	              className="h-8 text-xs"
129	              onClick={() => selectPreset(days)}
130	            >
131	              {label}
132	            </Button>
133	          ))}
134	
135	          {/* Custom date range picker */}
136	          <Popover>
137	            <PopoverTrigger asChild>
138	              <Button
139	                variant={activePreset === 0 ? "default" : "outline"}
140	                size="sm"
141	                className={cn("h-8 text-xs gap-1.5", activePreset === 0 && "font-medium")}
142	              >
143	                <CalendarIcon className="h-3.5 w-3.5" />
144	                {activePreset === 0 && dateRange?.from ? rangeLabel : "Custom"}
145	              </Button>
146	            </PopoverTrigger>
147	            <PopoverContent className="w-auto p-0" align="end">
148	              <Calendar
149	                mode="range"
150	                selected={dateRange}
151	                onSelect={handleRangeSelect}
152	                numberOfMonths={2}
153	                disabled={(date) => date > new Date()}
154	                initialFocus
155	                className={cn("p-3 pointer-events-auto")}
156	              />
157	            </PopoverContent>
158	          </Popover>
159	
160	          <Button
161	            variant="outline"
162	            size="sm"
163	            className="h-8"
164	            onClick={() => qc.invalidateQueries({ queryKey: ["admin_stats", fromISO, toISO] })}
165	            disabled={isFetching}
166	          >
167	            <RefreshCw className={`h-3.5 w-3.5 ${isFetching ? "animate-spin" : ""}`} />
168	          </Button>
169	        </div>
170	      </div>
171	
172	      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
173	        {cards.map(({ label, value, icon: Icon, color, subtitle }) => (
174	          <Card key={label}>
175	            <CardHeader className="flex flex-row items-center justify-between pb-2">
176	              <CardTitle className="text-sm font-medium text-muted-foreground">{label}</CardTitle>
177	              <Icon className={`h-4 w-4 ${color}`} />
178	            </CardHeader>
179	            <CardContent>
180	              {isLoading ? (
181	                <Skeleton className="h-8 w-20" />
182	              ) : (
183	                <>
184	                  <div className="text-2xl font-bold">
185	                    {typeof value === "string" ? value : (value?.toLocaleString() ?? 0)}
186	                  </div>
187	                  {subtitle && <p className="text-xs text-muted-foreground mt-1">{subtitle}</p>}
188	                </>
189	              )}
190	            </CardContent>
191	          </Card>
192	        ))}
193	      </div>
194	
195	      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
196	        <Card>
197	          <CardHeader className="pb-2">
198	            <CardTitle className="text-sm font-medium text-muted-foreground">Credits Usage ({rangeLabel})</CardTitle>
199	          </CardHeader>
200	          <CardContent>
201	            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
202	              <ResponsiveContainer width="100%" height={220}>
203	                <AreaChart data={chartData}>
204	                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
205	                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
206	                  <YAxis tick={{ fontSize: 11 }} className="text-muted-foreground" />
207	                  <Tooltip contentStyle={tooltipStyle} />
208	                  <Area type="monotone" dataKey="credits" stroke="hsl(var(--rk-primary))" fill="hsl(var(--primary) / 0.15)" strokeWidth={2} />
209	                </AreaChart>
210	              </ResponsiveContainer>
211	            )}
212	          </CardContent>
213	        </Card>
214	
215	        <Card>
216	          <CardHeader className="pb-2">
217	            <CardTitle className="text-sm font-medium text-muted-foreground">Revenue ({rangeLabel})</CardTitle>
218	          </CardHeader>
219	          <CardContent>
220	            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
221	              <ResponsiveContainer width="100%" height={220}>
222	                <AreaChart data={chartData}>
223	                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
224	                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
225	                  <YAxis tick={{ fontSize: 11 }} className="text-muted-foreground" />
226	                  <Tooltip contentStyle={tooltipStyle} formatter={(val: number) => [`$${val.toFixed(2)}`, "Revenue"]} />
227	                  <Area type="monotone" dataKey="revenue_dollars" stroke="hsl(var(--rk-success))" fill="hsl(var(--rk-success) / 0.15)" strokeWidth={2} />
228	                </AreaChart>
229	              </ResponsiveContainer>
230	            )}
231	          </CardContent>
232	        </Card>
233	
234	        <Card>
235	          <CardHeader className="pb-2">
236	            <CardTitle className="text-sm font-medium text-muted-foreground">Jobs Created ({rangeLabel})</CardTitle>
237	          </CardHeader>
238	          <CardContent>
239	            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
240	              <ResponsiveContainer width="100%" height={220}>
241	                <BarChart data={chartData}>
242	                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
243	                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
244	                  <YAxis tick={{ fontSize: 11 }} allowDecimals={false} className="text-muted-foreground" />
245	                  <Tooltip contentStyle={tooltipStyle} />
246	                  <Bar dataKey="jobs" fill="hsl(var(--rk-primary))" radius={[4, 4, 0, 0]} />
247	                </BarChart>
248	              </ResponsiveContainer>
249	            )}
250	          </CardContent>
251	        </Card>
252	
253	        <Card>
254	          <CardHeader className="pb-2">
255	            <CardTitle className="text-sm font-medium text-muted-foreground">User Signups ({rangeLabel})</CardTitle>
256	          </CardHeader>
257	          <CardContent>
258	            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
259	              <ResponsiveContainer width="100%" height={220}>
260	                <LineChart data={chartData}>
261	                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
262	                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
263	                  <YAxis tick={{ fontSize: 11 }} allowDecimals={false} className="text-muted-foreground" />
264	                  <Tooltip contentStyle={tooltipStyle} />
265	                  <Line type="monotone" dataKey="signups" stroke="hsl(var(--rk-primary))" strokeWidth={2} dot={{ r: 3, fill: "hsl(var(--rk-primary))" }} />
266	                </LineChart>
267	              </ResponsiveContainer>
268	            )}
269	          </CardContent>
270	        </Card>
271	      </div>
272	
273	      {/* Email Inbox Status Bar */}
274	      <div className="relative overflow-hidden rounded-xl border border-primary/20 bg-gradient-to-r from-primary/5 via-primary/10 to-primary/5 p-5">
275	        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-full -translate-y-1/2 translate-x-1/2" />
276	        <div className="absolute bottom-0 left-0 w-24 h-24 bg-primary/5 rounded-full translate-y-1/2 -translate-x-1/2" />
277	        <div className="relative flex items-center justify-between flex-wrap gap-4">
278	          <div className="flex items-center gap-4">
279	            <div className="w-12 h-12 rounded-xl bg-primary/15 flex items-center justify-center">
280	              <Inbox className="h-6 w-6 text-primary" />
281	            </div>
282	            <div>
283	              <div className="flex items-center gap-2">
284	                <h3 className="text-sm font-semibold text-foreground">Email Ingestion</h3>
285	                <Badge variant={emailConfig?.email_ingestion_enabled ? "success" : "secondary"}>
