288	              </div>
289	              <p className="text-xs text-muted-foreground mt-0.5">
290	                Users can forward resumes via email to auto-collect candidates into jobs.
291	              </p>
292	            </div>
293	          </div>
294	          <div className="flex items-center gap-3">
295	            <div className="text-right">
296	              <p className="text-lg font-bold text-foreground">{stats?.total_resumes ?? 0}</p>
297	              <p className="text-xs text-muted-foreground">Total resumes</p>
298	            </div>
299	            <div className="w-px h-8 bg-border" />
300	            <div className="text-right">
301	              <p className="text-lg font-bold text-foreground">{stats?.resumes_today ?? 0}</p>
302	              <p className="text-xs text-muted-foreground">Today</p>
303	            </div>
304	          </div>
305	        </div>
306	      </div>
307	
308	
309	    </div>
310	  );
311	};
312	
313	export default DashboardTab;
